extension CalimeroClient {
    /// The `consent` routes of the node API, one method per operation.
    public nonisolated var consent: Consent { Consent(client: self) }

    /// The `consent` routes of the node API (``CalimeroClient/consent``).
    public struct Consent: Sendable {
        let client: CalimeroClient

        /// Ask the account's owner to approve: `POST /consent/requests` (`consent_page_create`).
        ///
        /// From an app's frontend: an instance of a release or a deployment's offer (`install`: the install sheet, what gets created, where data can go and that updates wait for an approval; `outcome` names the `appId` and its `links`), an update policy (`updatePolicy`, an owner or admin of the organization), the node's updates page (`updates`, at `/updates/{request}`: the person unlocks it with their passkey, then it lists the updates waiting across the apps they approve and their organizations' policies), a release approval, an upgrade of its instance, outbound prefixes, a new organization, a new invite or joining with one, leaving an organization, a member's removal, role, teams or capabilities, an invite's revocation, an organization's name, its deletion, defaults or all-apps grants, approved on the node's own consent page (`url`), which takes the passkey. What the approval made (`orgId`, an invite's `token`, the `org` joined, a rename's `{ orgId, name }`, a deletion's `apps`) is in `/consent/{request}/result`'s `outcome`. 64 KiB at most.
        ///
        /// **Who:** a passkey session (an API key is refused).
        @discardableResult
        public func pageCreate(body: Operations.ConsentPageCreate.Input.Body.JsonPayload) async throws -> Components.Schemas.ConsentRequestMade {
            let input = Operations.ConsentPageCreate.Input(body: .json(body))
            return try await client.perform { api in
                try await api.consentPageCreate(input).ok.body.json
            }
        }

        /// What became of a consent request: `GET /consent/{request}/result` (`consent_page_result`).
        ///
        /// `decidedAt` (Unix seconds) is `null` while it is pending. `outcome`, once approved, is what the approval made: `{ orgId }` for `createOrg` (with `teamId`, the asking app's own team the organization starts with, when an app's frontend asked on a cluster that makes it), `{ token }` for `createInvite`, `{ org }` for `acceptInvite`, `{ orgId, name }` for `renameOrg`, `{ apps }` (the apps deleted) for `deleteOrg`; absent for the other kinds.
        ///
        /// **Who:** a passkey session (an API key is refused).
        @discardableResult
        public func pageResult(request: Swift.String) async throws -> Components.Schemas.ConsentResult {
            let input = Operations.ConsentPageResult.Input(path: .init(request: request))
            return try await client.perform { api in
                try await api.consentPageResult(input).ok.body.json
            }
        }
    }
}

