            return try await client.perform(nulls: nulls) { api in
                try await api.teamUpdate(input).ok.body.json
            }
        }
    }
}

extension CalimeroClient {
    /// The `packages` routes of the node API, one method per operation.
    public nonisolated var packages: Packages { Packages(client: self) }

    /// The `packages` routes of the node API (``CalimeroClient/packages``).
    public struct Packages: Sendable {
        let client: CalimeroClient

        /// Upload a raw component: `POST /bundles` (`bundle_put`).
        ///
        /// A `calimero:app` component, 16 MiB at most; only on a node started with `--allow-unsigned-bundles` or `--dev`. A WASM core module (SDK 0.12) is refused `400 UNSUPPORTED_BUNDLE`.
        ///
        /// **Who:** an installer (an account holder, or an unscoped API key that is not read-only).
        @discardableResult
        public func bundlePut(body: Data) async throws -> Components.Schemas.BundleStored {
            let input = Operations.BundlePut.Input(body: .applicationWasm(HTTPBody(body)))
            return try await client.perform { api in
                try await api.bundlePut(input).ok.body.json
            }
        }

        /// Register a frontend origin: `POST /package-origins/{package}` (`origins_add`).
        ///
        /// By whoever manages the package, with a passkey step-up over the change. Answers the origin as registered (the one already there, when the same origin is registered again).
        ///
        /// **Who:** an account holder (a passkey session not bound to an app's frontend). **Step-up:** answers `412 CONFIRM_REQUIRED` first; send the same request again with `confirm`, a passkey assertion over `details.challenge`.
        @discardableResult
        public func originsAdd(package: Swift.String, origin: Swift.String, rpId: Swift.String? = nil, served: Swift.Bool? = nil, passkey: (any PasskeyProvider)? = nil) async throws -> Components.Schemas.PackageOrigin {
            let input = Operations.OriginsAdd.Input(path: .init(package: package), body: .json(.init(origin: origin, rpId: rpId, served: served)))
            return try await client.perform(passkey: passkey) { api in
                try await api.originsAdd(input).ok.body.json
            }
        }

        /// A package's frontend origins: `GET /package-origins/{package}` (`origins_list`).
        ///
        /// The custom origins (and rp-ids) the package's manager registered for its frontend.
        ///
        /// **Who:** signed in (a session or an API key).
        @discardableResult
        public func originsList(package: Swift.String) async throws -> Components.Schemas.OriginList {
            let input = Operations.OriginsList.Input(path: .init(package: package))
            return try await client.perform { api in
                try await api.originsList(input).ok.body.json
            }
        }

        /// Remove a frontend origin: `DELETE /package-origins/{package}` (`origins_remove`).
        ///
        /// **Who:** an account holder (a passkey session not bound to an app's frontend). **Step-up:** answers `412 CONFIRM_REQUIRED` first; send the same request again with `confirm`, a passkey assertion over `details.challenge`.
        @discardableResult
        public func originsRemove(package: Swift.String, origin: Swift.String, passkey: (any PasskeyProvider)? = nil) async throws -> Components.Schemas.OriginRemoved {
            let input = Operations.OriginsRemove.Input(path: .init(package: package), body: .json(.init(origin: origin)))
            return try await client.perform(passkey: passkey) { api in
                try await api.originsRemove(input).ok.body.json
            }
        }

        /// A release's capabilities: `GET /packages/{package}/{version}/capabilities` (`package_capabilities`).
        ///
        /// What the release is and may do, read from its signed manifest and the ABI its service component embeds, before any app of it exists: `bundle` is the service WASM's hash, `outbound` the sorted prefixes it may call out to and `abi` the embedded `calimero:abi` verbatim (`null` when it embeds none). `destinations` is where an instance of it could send data, over the release and every app its `uses` would create with it (`members`, by path, each with its release, signer and own destinations), empty when no data leaves Calimero; both `null` while a release its `uses` would create is not installed here. `service` names the service whose card to read (default: the release's only one). A session bound to the package reads what its account does (every release of it recorded before releases were public or private). `404` for a release the caller may not see, `400 NO_SUCH_SERVICE` for an unknown service or no `service` on a release with several, `400 BAD_REQUEST` for an over-long `service`.
        ///
        /// **Who:** signed in (a session or an API key).
        @discardableResult
        public func capabilities(package: Swift.String, version: Swift.String, service: Swift.String? = nil) async throws -> Components.Schemas.CapabilityCard {
            let input = Operations.PackageCapabilities.Input(path: .init(package: package, version: version), query: .init(service: service))
            return try await client.perform { api in
                try await api.packageCapabilities(input).ok.body.json
            }
        }

        /// One package: `GET /packages/{package}` (`package_get`).
        ///
        /// The versions the caller may see; `404` when none.
        ///
        /// **Who:** signed in (a session or an API key).
        @discardableResult
        public func get(package: Swift.String) async throws -> Components.Schemas.Package {
            let input = Operations.PackageGet.Input(path: .init(package: package))
            return try await client.perform { api in
                try await api.packageGet(input).ok.body.json
            }
        }

        /// Install a release from the registry: `POST /packages/install` (`package_install`).
        ///
        /// For the organization `org` names (the caller a member, else `404`), else the caller's only one (`400 ORG_REQUIRED` in several). A release the registry serves without its credential is public: everyone here uses it. Else it is fetched with the credential and the caller's account, and is private: only the members of the organizations it was installed for use it, and an install for another adds that one; installed for none (the caller is in none), only the accounts that install it use it. `404` when the registry serves it to neither; `403 ACCOUNT_NOT_LINKED` when the registry refuses the caller's account as linked to no Calimero Cloud developer (link it in Calimero Cloud, under node accounts).
        ///
        /// **Who:** an installer (an account holder, or an unscoped API key that is not read-only).
        @discardableResult
        public func install(package: Swift.String, version: Swift.String, org: Swift.String? = nil) async throws -> Components.Schemas.PackageInstalled {
            let input = Operations.PackageInstall.Input(body: .json(.init(package: package, version: version, org: org)))
            return try await client.perform { api in
                try await api.packageInstall(input).ok.body.json
            }
        }

        /// Installed packages: `GET /packages` (`package_list`).
        ///
        /// Only the releases the caller may see.
        ///
        /// **Who:** signed in (a session or an API key).
        @discardableResult
        public func list() async throws -> Components.Schemas.PackageList {
            let input = Operations.PackageList.Input()
            return try await client.perform { api in
                try await api.packageList(input).ok.body.json
            }
        }

        /// A release's pipelines: `GET /packages/{package}/{version}/pipelines` (`package_pipelines`).
        ///
        /// The pipelines the release registers, by name: `hash`, `worstCaseFuel` (a decimal string), the `modules` they pin and the canonical `pipeline`. `404` for a release the caller may not see.
        ///
        /// **Who:** signed in (a session or an API key).
        @discardableResult
        public func pipelines(package: Swift.String, version: Swift.String) async throws -> Components.Schemas.ReleasePipelines {
            let input = Operations.PackagePipelines.Input(path: .init(package: package, version: version))
            return try await client.perform { api in
                try await api.packagePipelines(input).ok.body.json
            }
        }

        /// Uninstall a package: `DELETE /packages/{package}` (`package_uninstall`).
        ///
        /// Every version; refused while an app runs one.
        ///
        /// **Who:** an account holder (a passkey session not bound to an app's frontend).
        @discardableResult
        public func uninstall(package: Swift.String) async throws -> Components.Schemas.Uninstalled {
            let input = Operations.PackageUninstall.Input(path: .init(package: package))
            return try await client.perform { api in
                try await api.packageUninstall(input).ok.body.json
            }
        }

        /// Upload a signed release: `POST /packages` (`package_upload`).
        ///
        /// A signed `.mpk`, checked as an install from the registry is (signature, artifact digests, `minRuntimeVersion`, the package's pinned signer, every service compiles). Only with `--dev`; otherwise `403 UPLOADS_DISABLED`. An upload is private to the organization `org` names (the caller a member, else `404`), else the caller's only one: `400 ORG_REQUIRED` in several; in none, it is private to the accounts that install it.
        ///
        /// **Who:** an installer (an account holder, or an unscoped API key that is not read-only).
        @discardableResult
        public func upload(body: Data, org: Swift.String? = nil) async throws -> Components.Schemas.PackageInstalled {
            let input = Operations.PackageUpload.Input(query: .init(org: org), body: .binary(HTTPBody(body)))
            return try await client.perform { api in
                try await api.packageUpload(input).ok.body.json
            }
        }

        /// Uninstall one version: `DELETE /packages/{package}/{version}` (`package_version_uninstall`).
        ///
        /// **Who:** an account holder (a passkey session not bound to an app's frontend).
        @discardableResult
        public func versionUninstall(package: Swift.String, version: Swift.String) async throws -> Components.Schemas.Uninstalled {
            let input = Operations.PackageVersionUninstall.Input(path: .init(package: package, version: version))
            return try await client.perform { api in
                try await api.packageVersionUninstall(input).ok.body.json
            }
        }
    }
}

extension CalimeroClient {
    /// The `public` routes of the node API, one method per operation.
    public nonisolated var publicApi: Public { Public(client: self) }

    /// The `public` routes of the node API (``CalimeroClient/publicApi``).
    public struct Public: Sendable {
        let client: CalimeroClient

        /// The node's attestation: `GET /attestation` (`attestation`).
        ///
        /// In the clear. A TDX quote binding the node's transport key (or, with `purpose=receipts`, its receipt key and the governance; with `purpose=kms`, what it verified of its KMS; with `purpose=orchestrator`, the cluster identity this replica holds) to `nonce`; `app`/`appHash` bind an app's bundle hash: `app` only an app anyone may reach (public), any other answering `404` as an unknown id does, so it never says that a private app exists. A client checks it before it seals anything to the key. The node makes one quote at a time and lets a few requests wait for it: past that `503 BUSY` with `Retry-After: 1`, ask again then.
        ///
        /// **Who:** anyone.
        @discardableResult
        public func attestation(nonce: Swift.String, app: Swift.String? = nil, appHash: Swift.String? = nil, purpose: Operations.Attestation.Input.Query.PurposePayload? = nil) async throws -> Components.Schemas.AttestationDoc {
            let input = Operations.Attestation.Input(query: .init(nonce: nonce, app: app, appHash: appHash, purpose: purpose))
            return try await client.perform { api in
                try await api.attestation(input).ok.body.json
            }
        }

        /// Node health: `GET /health` (`health`).
        ///
        /// In the clear. The node's id, the system group's leader (`null`: none known), its `merod` release, the newest cluster version it supports (`clusterVersion`) and the cluster's rollback epoch (`null` on a node without a rollback counter).
        ///
        /// **Who:** anyone.
        @discardableResult
        public func health() async throws -> Components.Schemas.Health {
            let input = Operations.Health.Input()
            return try await client.perform { api in
                try await api.health(input).ok.body.json
            }
        }

        /// Whether a signing key is bound: `GET /publishers/{signer}` (`publisher_binding`).
        ///
        /// Whether a package signing key (`did:key`) is bound to an organization on this cluster (`bound`, never which), and its binding generation (`0`: never bound).
        ///
        /// **Who:** signed in (a session or an API key).
        @discardableResult
        public func publisherBinding(signer: Swift.String) async throws -> Components.Schemas.PublisherBinding {
            let input = Operations.PublisherBinding.Input(path: .init(signer: signer))
            return try await client.perform { api in
                try await api.publisherBinding(input).ok.body.json
            }
        }

        /// The cluster's releases: `GET /releases` (`releases_public`).
        ///
        /// The cluster's governance and the deadlines set on mero-tee releases, oldest release first: after `after` (RFC 3339; `afterSecs` Unix seconds) a scope that has not approved that release (or a newer one) starts no new work.
        ///
        /// **Who:** anyone.
        @discardableResult
        public func releasesPublic() async throws -> Components.Schemas.ClusterReleases {
            let input = Operations.ReleasesPublic.Input()
            return try await client.perform { api in
                try await api.releasesPublic(input).ok.body.json
            }
        }

        /// Bring an organization's or account's apps back from its recovery files: `POST /recover/holder` (`restore_recover_holder`).
        ///
        /// Sent by the holder's own device, over the sealed channel: its newest `holder` file (`slice`), each app's file and the code files, in the receiving node's `--recovery-dir` (or `--recover-from`) under `org-<id>/` or `account-<id>/`, each with the data key the holder opened from it with its backup key (hex). The cluster admits it with the operator's signature over `cluster / __recover_holder / { holder, slice, apps: [{ app, file, sha256 }] }` (`428` first, naming it). Where owners upgrade apps, and only for an organization, account, apps and passkeys the cluster does not hold; the receiving node seeds each app, which answers `409 APP_RESTORING` until its replicas hold it. People sign in again with the passkeys they had.
        ///
        /// **Who:** anyone. **Operator signature:** answers `428 OPERATOR_SIGNATURE_REQUIRED` first; send it again with `operatorProof`, the operator key's signature over `details.message` and its `nonce`.
        @discardableResult
        public func restoreRecoverHolder(holder: Swift.String, slice: Operations.RestoreRecoverHolder.Input.Body.JsonPayload.SlicePayload, apps: Operations.RestoreRecoverHolder.Input.Body.JsonPayload.AppsPayload? = nil, code: Operations.RestoreRecoverHolder.Input.Body.JsonPayload.CodePayload? = nil, operatorSigner: (any OperatorSigner)? = nil) async throws -> Components.Schemas.HolderRecovered {
            let input = Operations.RestoreRecoverHolder.Input(body: .json(.init(holder: holder, slice: slice, apps: apps, code: code)))
            return try await client.perform(operatorSigner: operatorSigner) { api in
                try await api.restoreRecoverHolder(input).ok.body.json
            }
        }
    }
}
